mapper.select:
SELECT bu.id AS bu_id, bu.usuario_id AS usuarioId, bu.baraja_publica_id AS barajaPublicaId, bu.fecha_creacion AS fechaCreacion, b.id AS b_id, b.nombre AS b_nombre, cb.baraja_id, cb.expansion_id, cb.carta_juego_id, cb.orden FROM baraja_usuario bu JOIN baraja b ON b.id = bu.baraja_id LEFT JOIN carta_baraja cb ON cb.baraja_id = b.id
AND EXISTS ( SELECT 1 FROM carta_baraja cb2 JOIN carta c ON c.expansion_id = cb2.expansion_id AND c.carta_juego_id = cb2.carta_juego_id WHERE cb2.baraja_id = b.id AND c.nombre LIKE CONCAT('%', #{cartaNombre}, '%') )
AND bu.usuario_id = #{usuarioId}
AND bu.baraja_publica_id = #{barajaPublicaId}
ORDER BY ${ordenacion}, cb.orden ASC
ORDER BY bu.fecha_creacion DESC, cb.orden ASC
